#!/usr/bin/env node
// Derives the Codex plugin from the Claude plugin's agent and package.json. Codex copies a plugin's
// own directory into its cache, so the prompt cannot be linked from plugin/ and is generated instead.
// With --check, fails when a generated file is stale instead of writing it.
import { readFileSync, writeFileSync } from "node:fs";

const check = process.argv.includes("--check");
const { version } = JSON.parse(readFileSync("package.json", "utf8"));
const agent = readFileSync("plugin/agents/librarian.md", "utf8");
const body = /^---\n[\s\S]*?\n---\n\n([\s\S]*)$/.exec(agent)?.[1];
if (!body) throw new Error("plugin/agents/librarian.md has no frontmatter and body");

const manifestPath = "codex-plugin/.codex-plugin/plugin.json";
const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));

const outputs = {
  [manifestPath]: `${JSON.stringify({ ...manifest, version }, null, 2)}\n`,
  "codex-plugin/skills/librarian/references/librarian-prompt.md": [
    "<!-- Generated by scripts/sync-codex-plugin.mjs from plugin/agents/librarian.md; edit that file. -->",
    "",
    `When \`librarian\` is not on your PATH, run \`npx --yes @thurstonsand/pi-librarian@${version}\` wherever these instructions say \`librarian\`.`,
    "",
    "The command needs the network and writes its cache under `~/.cache/agents/librarian`. When the sandbox blocks it, rerun the same command with escalated permissions and a one-line justification; do not work around the sandbox by moving its cache or running a copy you found.",
    "",
    body,
  ].join("\n"),
};

const stale = [];
for (const [file, content] of Object.entries(outputs)) {
  const existing = readFileSync(file, "utf8");
  // Biome owns the JSON formatting, so a manifest is stale only when its value differs.
  const same = file.endsWith(".json")
    ? JSON.stringify(JSON.parse(existing)) === JSON.stringify(JSON.parse(content))
    : existing === content;
  if (same) continue;
  if (check) stale.push(file);
  else writeFileSync(file, content);
}
if (stale.length > 0) {
  console.error(`Stale, run scripts/sync-codex-plugin.mjs: ${stale.join(", ")}`);
  process.exit(1);
}
